FINAL_REPORT_DAYS = 30


# Intermediate report delay in hours
INTERMEDIATE_REPORT_HOURS = 72


def initial_report_deadline(aware_at: datetime, classified_at: datetime) -> datetime:
    """When the initial notification of a major incident is due."""
    # Deadline is the earlier of 24 hours after awareness or 4 hours after classification
    deadline_from_awareness = aware_at + timedelta(hours=INITIAL_REPORT_HOURS)
    deadline_from_classification = classified_at + timedelta(hours=4)
    # The initial report deadline is the earlier of these two
    return min(deadline_from_awareness, deadline_from_classification)


def final_report_deadline(previous_report_at: datetime) -> datetime:
    """When the final report is due, counted from the previous report."""
    return previous_report_at + timedelta(days=FINAL_REPORT_DAYS)


def reporting_plan(aware_at: datetime, classified_at: datetime) -> list[dict]:
    """The reports to send for one major incident, in order, each with its due time."""
    initial = initial_report_deadline(aware_at, classified_at)
    intermediate = initial + timedelta(hours=INTERMEDIATE_REPORT_HOURS)
    final = final_report_deadline(intermediate)
    return [
        {"report": "initial", "due": initial},
        {"report": "intermediate", "due": intermediate},
        {"report": "final", "due": final},
